module parity_8bit (
    input [7:0] in,
    output out
);
    assign out = ^in;
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire s1_n, s0_n;
    wire term0, term1, term2, term3;

    not (s1_n, sel[1]);
    not (s0_n, sel[0]);

    and (term0, in[0], s1_n, s0_n);
    and (term1, in[1], s1_n, sel[0]);
    and (term2, in[2], sel[1], s0_n);
    and (term3, in[3], sel[1], sel[0]);

    or (out, term0, term1, term2, term3);
endmodule

module majority (
    input a, b, c,
    output out
);
    assign out = (a & b) | (a & c) | (b & c);
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);

    // gray[3]: Invert the MSB
    assign gray[3] = ~binary[3];

    // gray[2]: XOR of MSB and bit 2
    assign gray[2] = binary[3] ^ binary[2];

    // gray[1]: XOR of bit 1 and bit 0
    assign gray[1] = binary[1] ^ binary[0];

    // gray[0]: Invert bit 0
    assign gray[0] = ~binary[0];

endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

    assign equal = (a == b);

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

assign out = 4'b0001 << in;

endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(*) begin
    if (in[3])
        code = 2'b11;
    else if (in[2])
        code = 2'b10;
    else if (in[1])
        code = 2'b01;
    else
        code = 2'b00;
end

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

reg [1:0] current_state, next_state;

localparam s0 = 2'b00,
           s1 = 2'b01,
           s2 = 2'b10;

always @(posedge clk) begin
    if (reset)
        current_state <= s0;
    else
        current_state <= next_state;
end

always @(*) begin
    case (current_state)
        s0: next_state = s1;
        s1: next_state = s2;
        s2: next_state = s0;
        default: next_state = s0;
    endcase
end

assign light[0] = (current_state == s0);
assign light[1] = (current_state == s1);
assign light[2] = (current_state == s2) ? 1'b1 : 1'b0;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    parameter [1:0] STATE_RESET = 2'b00,
                    STATE_START = 2'b01,
                    STATE_WAIT = 2'b10;

    reg [1:0] state_reg, state_next;

    always @(posedge clk or posedge reset) begin
        if (reset)
            state_reg <= STATE_RESET;
        else
            state_reg <= state_next;
    end

    always @(*) begin
        case (state_reg)
            STATE_RESET: 
                state_next = up_request ? STATE_START : STATE_RESET;
            STATE_START: 
                state_next = down_request ? STATE_START : STATE_WAIT;
            STATE_WAIT: 
                state_next = down_request ? STATE_START : STATE_WAIT;
            default: 
                state_next = STATE_RESET;
        endcase
    end

    assign state = state_reg;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

reg [1:0] state_reg;

assign state = state_reg;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state_reg <= 2'b00;
    end else begin
        if (coin_inserted) begin
            state_reg <= 2'b00;
        end else if (item_selected) begin
            case (state_reg)
                2'b00: state_reg <= 2'b01;
                2'b01: state_reg <= 2'b10;
                2'b10: state_reg <= 2'b11;
                2'b11: state_reg <= 2'b11;
                default: state_reg <= 2'b00;
            endcase
        end else begin
            state_reg <= state_reg;
        end
    end
end

endmodule

module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);
    assign out = in_0 >>> in_1;
endmodule

module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);

reg [7:0] fixed_value;

always @(*) begin
    if (in_0 < 16'sd32767)
        fixed_value = 8'sd0;
    else if (in_0 > 16'sd32768)
        fixed_value = 8'sd1;
    else
        fixed_value = 8'sd2;
end

assign out = fixed_value;

endmodule

module add_8bit (
    input signed [7:0] a, b,
    output signed [8:0] out
);
    // Zero-extend inputs to 8 bits and compute sum as 9-bit signed
    assign out = $signed({1'b0, a}) + $signed({1'b0, b});
endmodule

module mult_4bit (
    input [3:0] a, b,
    output [7:0] out
);

    // Generate and propagate signals for each bit
    wire g0, g1, g2, g3;
    wire p0, p1, p2, p3;

    assign g0 = a[0] & b[0];
    assign p0 = a[0] ^ b[0];

    assign g1 = a[1] & b[1];
    assign p1 = a[1] ^ b[1];

    assign g2 = a[2] & b[2];
    assign p2 = a[2] ^ b[2];

    assign g3 = a[3] & b[3];
    assign p3 = a[3] ^ b[3];

    // Carry lookahead computation for each stage
    wire c1, c2, c3, c4;

    assign c1 = g0 | (p0 & 1'b0);
    assign c2 = g1 | (p1 & g0) | (p1 & p0 & 1'b0);
    assign c3 = g2 | (p2 & g1) | (p2 & p1 & g0) | (p2 & p1 & p0 & 1'b0);
    assign c4 = g3 | (p3 & g2) | (p3 & p2 & g1) | (p3 & p2 & p1 & g0) | (p3 & p2 & p1 & p0 & 1'b0);

    // Sum bits calculation
    assign out[0] = p0 ^ 1'b0;
    assign out[1] = p1 ^ c1;
    assign out[2] = p2 ^ c2;
    assign out[3] = p3 ^ c3;
    assign out[7] = c4;

endmodule

module subtract_8bit (
    input signed [7:0] a, b,
    output signed [8:0] diff
);
    // Sign-extend inputs to 9 bits
    wire signed [8:0] in1_ext = {a[7], a};
    wire signed [8:0] in2_ext = {b[7], b};

    // Intermediate signals
    wire signed [8:0] sum_18 = in1_ext + in2_ext;
    wire signed [8:0] sum_17 = sum_18 >> 1;

    // Correct sign for sum_17
    wire signed [8:0] sum_17_correct = (sum_17 < 0) ? {1'b1, sum_17[7:0]} : sum_17;

    // Final subtraction
    assign diff = sum_17_correct - in2_ext;
endmodule

module bitwise_ops (
    input [7:0] a, b,
    output [7:0] and_out,
    output [7:0] or_out,
    output [7:0] xor_out
);

    assign and_out = a & b;
    assign or_out = a | b;
    assign xor_out = a ^ b;

endmodule

module left_shift (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

assign out = in << shift;

endmodule

module bitwise_not (
    input [7:0] in,
    output [7:0] out
);

    assign out = ~in;

endmodule

module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

wire [7:0] stage1, stage2;

// Stage 1: Shift left by 1 if shift[0] is set
assign stage1 = shift[0] ? {in[6:0], in[7]} : in;

// Stage 2: Shift left by 2 if shift[1] is set
assign stage2 = shift[1] ? {stage1[5:0], stage1[7:6]} : stage1;

// Stage 3: Shift left by 4 if shift[2] is set
assign out = shift[2] ? {stage2[3:0], stage2[7:4]} : stage2;

endmodule

module relu (
    input signed [15:0] in_0,
    output signed [15:0] out);
    wire [15:0] b;
    assign b = in_0 & 16'hffff; // Compute two's complement of in_0
    assign out = (in_0[6]) ? 16'd0 : b;
endmodule

module caesar_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    wire [7:0] A_adj;
    wire [8:0] carry;

    assign A_adj = {~data_in[7], data_in[6:0]}; // Adjust input for right shift
    assign carry[0] = 1'b0;

    generate
        genvar i;
        for (i = 0; i < 8; i = i + 1) begin : gen_sub
            wire A_adj_x = (i >= 7) ? ~data_in[7] : data_in[i];
            assign data_out[i] = A_adj_x ^ carry[i];
            assign carry[i + 1] = A_adj_x & carry[i];
        end
    endgenerate
endmodule

module modular_add_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

assign data_out = data_in + 4;

endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key

    wire [7:0] key_extended = {4'b0, KEY};
    assign data_out[7:4] = data_in[7:4] ^ key_extended[3:0];
    assign data_out[3:0] = data_in[3:0];

endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);

reg [2:0] counter;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
    end else begin
        counter <= counter + 1;
    end
end

assign clk_out = counter[1];

endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire [3:0] eq;
    wire [3:0] gt;
    wire [3:0] lt;

    // Equality check using XNOR
    assign eq = a ~^ b;

    // Greater than check using AND-OR logic
    assign gt[0] = 1'b0;
    assign gt[1] = eq[0] & a[1] & ~b[1];
    assign gt[2] = eq[1] & eq[0] & a[2] & ~b[2];
    assign gt[3] = eq[2] & eq[1] & eq[0] & a[3] & ~b[3];

    // Less than check using AND-OR logic
    assign lt[0] = 1'b0;
    assign lt[1] = ~eq[0] & b[1];
    assign lt[2] = ~eq[1] & ~eq[0] & b[2];
    assign lt[3] = ~eq[2] & ~eq[1] & ~eq[0] & b[3];

    // Compute outputs
    assign gt = ~(gt[0] | gt[1] | gt[2] | gt[3]);
    assign eq = gt[3];
    assign lt = ~(lt[0] | lt[1] | lt[2] | lt[3]);
endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);

assign out[0] = enable & (in == 2'b00);
assign out[1] = enable & (in == 2'b01);
assign out[2] = enable & (in == 2'b10);
assign out[3] = enable & (in == 2'b11);

endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out);

    assign out[0] = enable & ~in[1] & ~in[0];
    assign out[1] = enable & ~in[1] &  in[0];
    assign out[2] = enable &  in[1] & ~in[0];
    assign out[3] = enable &  in[1] &  in[0];

endmodule

module demux_1to2 (
    input  in,
    input  sel,
    output out0,
    output out1
);

    assign out0 = in & ~sel;
    assign out1 = in & sel;

endmodule

module demux_1to4 (
    input        in,
    input  [1:0] sel,
    output       out0,
    output       out1,
    output       out2,
    output       out3
);

    // Generate out0 and out1 using AND gates with appropriate input assignments
    assign out0 = sel[0] ? in : 1'b0;  // sel[0] acts as enable for out0
    assign out1 = sel[1] ? in : 1'b0;  // sel[1] acts as enable for out1

    // Note: out2 and out3 are declared but not implemented as per the problem's constraints
    // They should be connected to other logic (e.g., LED3/LED4) which is not specified here

endmodule

module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

reg [3:0] counter_one;
reg [3:0] counter_two;

// Counter One logic
always @(posedge clk) begin
    if (rst) begin
        counter_one <= 4'b0;
    end else begin
        counter_one <= counter_one + 1;
    end
end

// Counter Two logic
always @(posedge clk) begin
    if (rst) begin
        counter_two <= 4'b0;
    end else begin
        counter_two <= counter_two + 1;
    end
end

// Combine counters and apply XOR
assign count = (counter_one + counter_two) ^ 8'h3B;

endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] q_reg;
wire [3:0] d_next;

assign d_next[0] = ~q_reg[3];
assign d_next[1] = q_reg[0];
assign d_next[2] = q_reg[1];
assign d_next[3] = q_reg[2];

assign q = q_reg;

always @(posedge clk) begin
    if (rst) begin
        q_reg <= 4'b0000;
    end else begin
        q_reg <= d_next;
    end
end

endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);

reg [7:0] shift_reg;

always @(posedge clk) begin
    if (rst) begin
        shift_reg <= 8'b0;
    end else begin
        if (load) begin
            shift_reg <= pin;
        end else begin
            shift_reg <= shift_reg << 1;
        end
    end
end

assign sout = shift_reg[7];

endmodule

module ring_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] shift_reg;

always @(posedge clk) begin
    if (rst) begin
        shift_reg <= 4'b0001;
    end else begin
        shift_reg <= (shift_reg << 1) | (shift_reg >> 3);
    end
end

assign q = shift_reg;

endmodule

module sipo_8bit(
    input clk,
    input rst,
    input sin,
    output [7:0] pout
);

reg [7:0] temp_reg;

always @(posedge clk) begin
    if (rst)
        temp_reg <= 8'b0;
    else
        temp_reg <= {temp_reg[6:0], sin};
end

assign pout = temp_reg;

endmodule

module siso_8bit(
    input clk,
    input rst,
    input sin,
    output sout
);

reg [6:0] q;

always @(posedge clk) begin
    if (rst) begin
        q <= 7'b0;
    end else begin
        q <= {q[5:0], sin};
    end
end

assign sout = q[6];

endmodule

module up_counter8(
    input clk,
    input rst,
    output [7:0] count
);

reg [7:0] count;

always @(posedge clk) begin
    if (rst)
        count <= 8'b0;
    else
        count <= count + 1'b1;
end

assign count = count;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  parameter [1:0] c0 = 2'b00,
                  c1 = 2'b01,
                  c2 = 2'b10,
                  c3 = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge resetn) begin
    if (clk)
      current_state <= c0;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      c0: begin
        if (r[0])
          next_state = c1;
        else if (r[1])
          next_state = c2;
        else if (r[2])
          next_state = c3;
        else
          next_state = c0;
      end
      c1: begin
        if (r[0])
          next_state = c2;
        else if (r[1])
          next_state = c3;
        else if (r[2])
          next_state = c0;
        else
          next_state = c1;
      end
      c2: begin
        if (r[0])
          next_state = c3;
        else if (r[1])
          next_state = c0;
        else if (r[2])
          next_state = c1;
        else
          next_state = c2;
      end
      c3: begin
        if (r[0])
          next_state = c0;
        else if (r[1])
          next_state = c1;
        else if (r[2])
          next_state = c2;
        else
          next_state = c3;
      end
      default: next_state = c0;
    endcase
  end

  assign g = (current_state == c0) ? 3'b000 :
               (current_state == c1) ? 3'b001 :
               (current_state == c2) ? 3'b010 :
               3'b011;

endmodule

module TopModule (
  input p1a,
  input p1b,
  input p1c,
  input p1d,
  input p1e,
  input p1f,
  output p1y,
  input p2a,
  input p2b,
  input p2c,
  input p2d,
  output p2y
);

  wire t1, t2, t3;

  assign t1 = p1a & p1b & p1c;
  assign t2 = p1d & p1e & p1f;
  assign t3 = (p2a & p2b) | (p2c & p2d);

  assign p1y = t1 | t2;
  assign p2y = t3;

endmodule

module TopModule (
  input a,
  input b,
  output out_assign,
  output reg out_alwaysblock
);

  wire AND_result;

  assign AND_result = a & b;
  assign out_assign = AND_result;

  always @(*) begin
    out_alwaysblock = AND_result;
  end

endmodule

module TopModule (
  input clk,
  input a,
  input b,
  output out_assign,
  output reg out_always_comb,
  output reg out_always_ff
);

  assign out_assign = a ^ b;

  always @(posedge clk) begin
    out_always_comb <= a ^ b;
    out_always_ff <= out_assign;
  end

endmodule

module TopModule (
  input a,
  input b,
  input sel_b1,
  input sel_b2,
  output out_assign,
  output reg out_always
);

  wire selected_data;
  assign selected_data = (~sel_b1) ? a :
                         (sel_b1 & sel_b2) ? b :
                         1'b0;

  assign out_assign = selected_data;
  always @* begin
    out_always = selected_data;
  end

endmodule

module TopModule (
  input cpu_overheated,
  output reg shut_off_computer,
  input arrived,
  input gas_tank_empty,
  output reg keep_driving
);

  // Delay registers for input synchronization and data storage
  reg [1:0] sw_delay;
  reg [1:0] key_delay;

  // Synchronize cpu_overheated and shut_off_computer to prevent metastability
  always @(posedge cpu_overheated) begin
    sw_delay <= {sw_delay[0], shut_off_computer};
    key_delay <= {key_delay[0], gas_tank_empty};
  end

  // Current and previous states for edge detection
  reg [1:0] sw_state;
  reg [1:0] key_state;

  // Detect rising edges of shut_off_computer and gas_tank_empty
  wire sw_rise = sw_state[1] && !sw_delay[1];
  wire key_rise = key_state[1] && !key_delay[1];

  // State transition logic
  always @(posedge cpu_overheated) begin
    sw_state <= sw_delay;
    key_state <= key_delay;
  end

  // Output logic with reset
  always @(posedge cpu_overheated) begin
    if (arrived) begin
      keep_driving <= 1'b0;
    end else begin
      if (sw_rise) begin
        keep_driving <= 1'b0;
      end else if (key_rise) begin
        keep_driving <= 1'b1;
      end
    end
  end

endmodule

module TopModule (
  input [15:0] scancode,
  output reg left,
  output reg down,
  output reg right,
  output reg up
);

always @(*) begin
  case (scancode)
    16'h0000: begin // ADD
      left = 1'b1;
      down = 1'b1;
      right = 1'b0;
      up = 1'b0;
    end
    16'h0001: begin // SUB
      left = 1'b1;
      down = 1'b1;
      right = 1'b0;
      up = 1'b0;
    end
    16'h0002: begin // AND
      left = 1'b1;
      down = 1'b1;
      right = 1'b0;
      up = 1'b0;
    end
    16'h0003: begin // OR
      left = 1'b1;
      down = 1'b1;
      right = 1'b0;
      up = 1'b0;
    end
    16'h0004: begin // JUMP
      left = 1'b0;
      down = 1'b0;
      right = 1'b1;
      up = 1'b0;
    end
    16'h0005: begin // BRANCH
      left = 1'b0;
      down = 1'b0;
      right = 1'b1;
      up = 1'b1;
    end
    default: begin
      left = 1'b0;
      down = 1'b0;
      right = 1'b0;
      up = 1'b0;
    end
  endcase
end

endmodule

module TopModule (
  input a,
  input b,
  output out
);
  assign out = a ? b : 1'b0;
endmodule

module TopModule (
  input [7:0] code,
  output reg [3:0] out,
  output reg valid
);

always @(*) begin
  case (code)
    8'h30: begin // '0'
      out = 4'd0;
      valid = 0;
    end
    8'h31: begin // '1'
      out = 4'd1;
      valid = 0;
    end
    8'h32: begin // '2'
      out = 4'd2;
      valid = 0;
    end
    8'h33: begin // '3'
      out = 4'd3;
      valid = 0;
    end
    8'h34: begin // '4'
      out = 4'd4;
      valid = 0;
    end
    8'h35: begin // '5'
      out = 4'd5;
      valid = 0;
    end
    8'h36: begin // '6'
      out = 4'd6;
      valid = 0;
    end
    8'h37: begin // '7'
      out = 4'd7;
      valid = 0;
    end
    8'h38: begin // '8'
      out = 4'd8;
      valid = 0;
    end
    8'h39: begin // '9'
      out = 4'd9;
      valid = 0;
    end
    default: begin
      out = 4'd10;
      valid = 1;
    end
  endcase
end

endmodule

module TopModule (
  input a,
  input b,
  output q
);
  assign q = a ? b : 1'b0;
endmodule

module TopModule (
  input clk,
  input a,
  output reg q
);

  always @(posedge clk) begin
    if (a)
      q <= 1'b0;
    else
      q <= 1'b1;
  end

endmodule

module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  always @(posedge clk) begin
    if (reset)
      q <= 4'b0;
    else
      q <= q + 1'b1;
  end

endmodule

module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  always @(posedge clk) begin
    if (reset) begin
      q <= 4'd9;
