  reg [1:0] next_state;

  localparam [1:0] IDLE = 2'b01,
                   N1   = 2'b00,
                   N2   = 2'b10,
                   N3   = 2'b11;

  // State transition logic
  always @(*) begin
    case (current_state)
      IDLE: next_state = train_valid ? (train_taken ? N3 : N1) : IDLE;
      N1:   next_state = train_valid ? (train_taken ? N3 : N2) : N1;
      N2:   next_state = train_valid ? (train_taken ? N1 : N3) : N2;
      N3:   next_state = train_valid ? (train_taken ? N2 : N1) : N3;
      default: next_state = IDLE;
    endcase
  end

  // State register
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      current_state <= IDLE;
    end else begin
      current_state <= next_state;
    end
  end

  assign state = current_state;

endmodule

