      current_state <= S0;
    end else begin
      current_state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      S0: next_state = x ? S1 : S2;
      S1: next_state = S0;
      S2: next_state = S0;
      default: next_state = S0;
    endcase
  end

  // Output logic
  assign z = (current_state == S1) ? x : ~x;

endmodule

