module TopModule (
  input clk,
  input reset,
  input in,
  output disc,
  output flag,
  output err
);

// State definitions
parameter IDLE    = 4'd0;
parameter MR_M1   = 4'd1;
parameter MR_M2   = 4'd2;
parameter MR_M3   = 4'd3;
parameter MR_M4   = 4'd4;
parameter MR_M5   = 4'd5;
parameter MR_M6   = 4'd6;
parameter NOT_MR_M3 = 4'd7;
parameter NOT_MR_M4 = 4'd8;
parameter NOT_MR_M5 = 4'd9;
parameter NOT_MR_M6 = 4'd10;
parameter RGB     = 4'd11;

reg [3:0] current_state, next_state;

// State transition logic
always @(posedge clk) begin
  if (reset)
    current_state <= IDLE;
  else
    current_state <= next_state;
end

// Next state logic
always @(*) begin
  case (current_state)
    IDLE:    next_state = in ? MR_M1 : IDLE;
    MR_M1:   next_state = in ? MR_M2 : MR_M1;
    MR_M2:   next_state = in ? MR_M3 : MR_M2;
    MR_M3:   next_state = in ? MR_M4 : MR_M3;
    MR_M4:   next_state = in ? MR_M5 : MR_M4;
    MR_M5:   next_state = in ? MR_M6 : MR_M5;
    MR_M6:   next_state = NOT_MR_M3;
    NOT_MR_M3: next_state = NOT_MR_M4;
    NOT_MR_M4: next_state = NOT_MR_M5;
    NOT_MR_M5: next_state = NOT_MR_M6;
    NOT_MR_M6: next_state = RGB;
    RGB:     next_state = IDLE;
    default: next_state = IDLE;
  endcase
end

// Output assignments
assign disc = (current_state == MR_M3);
assign flag = (current_state == MR_M4);
assign err = (current_state == MR_M5);

endmodule

