            ST_SET = 2'd1,
            ST_WAIT = 2'd2;

  // State transition
  always @(posedge clk) begin
    if (reset)
      current_state <= ST_IDLE;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      ST_IDLE: next_state = (in[3]) ? ST_SET : ST_IDLE;
      ST_SET: next_state = ST_WAIT;
      ST_WAIT: next_state = (in[3]) ? ST_WAIT : ST_IDLE;
      default: next_state = ST_IDLE;
    endcase
  end

  // Output logic
  always @(posedge clk) begin
    if (reset)
      output_reg <= 1'b0;
    else
      output_reg <= (current_state == ST_SET);
  end

  assign done = output_reg;

endmodule

module TopModule (
  input clk,
  input in,
  input reset,
  output done
);

  localparam [1:0] IDLE = 2'b00,
                   PULSE_GEN = 2'b01,
                   WAIT = 2'b10;

  reg [1:0] current_state, next_state;
  reg [2:0] counter;
  reg active;

  // State transition
  always @(posedge clk) begin
    if (in)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      IDLE: 
        next_state = (reset && !active) ? PULSE_GEN : IDLE;
      PULSE_GEN: 
        next_state = (counter == 3'd4) ? WAIT : PULSE_GEN;
      WAIT: 
        next_state = (reset) ? WAIT : IDLE;
      default: 
        next_state = IDLE;
    endcase
  end

  // Counter and active control
  always @(posedge clk) begin
    if (in) begin
      counter <= 3'b0;
      active <= 1'b0;
    end else begin
      case (current_state)
        PULSE_GEN: begin
          if (counter < 3'd4)
            counter <= counter + 1;
          else
            counter <= 3'b0;
        end
        default: 
          counter <= 3'b0;
      endcase

      if (current_state == IDLE && reset)
        active <= 1'b1;
      if (current_state == WAIT || in)
        active <= 1'b0;
    end
  end

  // Output assignment
  assign done = (current_state == PULSE_GEN) ? active : 1'b0;

endmodule

