module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  output walk_left,
  output walk_right
);

  localparam S0 = 1'b0;
  localparam S1 = 1'b1;

  reg state;

  assign walk_left = ~state;
  assign walk_right = state;

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= S0;
    end else begin
      case (state)
        S0: state <= (bump_left) ? S1 : S0;
        S1: state <= (bump_right) ? S0 : S1;
        default: state <= S0;
      endcase
    end
  end

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  localparam IDLE = 2'b00,
             START = 2'b01,
             LOAD = 2'b10,
             DONE = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      current_state <= IDLE;
    end else begin
      current_state <= next_state;
    end
  end

  always @(*) begin
    case (current_state)
      IDLE: next_state = bump_left ? START : IDLE;
      START: next_state = bump_right ? LOAD : START;
      LOAD: begin
        if (ground)
          next_state = bump_right ? DONE : LOAD;
        else
          next_state = LOAD;
      end
      DONE: next_state = bump_left ? DONE : IDLE;
      default: next_state = IDLE;
    endcase
  end

  assign walk_left = (current_state == IDLE);
  assign walk_right = (current_state == LOAD);
  assign aaah = (current_state == IDLE) || (current_state == DONE);

endmodule

