      // Update shift register with new button input
      shift_reg <= {shift_reg[1:0], data};
      // Detect rising edge of data and set output accordingly
      if (data && !shift_reg[2])
        btn_out <= 1'b1;
      else if (!data && shift_reg[2])
        btn_out <= 1'b0;
    end
  end

  assign start_shifting = btn_out;

