module TopModule (
  input [3:0] x,
  output logic f
);

  wire not_X0, not_X2;
  wire and_out;
  wire nor_out;

  // Invert x[0] and x[2]
  not(not_X0, x[0]);
  not(not_X2, x[2]);

  // AND the inverted signals
  and(and_out, not_X0, not_X2);

  // NOR the remaining inputs with the AND result
  nor(nor_out, x[1], x[3], and_out);

  // Invert the NOR result to get the final output
  not(f, nor_out);

endmodule

module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  // One-hot encoding assumes state[9:0] has exactly one bit set
  wire current_node = (state[0] == 1'b1) ? 1'b0 :
                      (state[1] == 1'b1) ? 1'b1 : 1'b0;

  // Compute in-degree as sum of active parent edges
  wire [3:0] parent_mask = state[3:0];
  wire in_degree = (parent_mask[0] & d) + 
                   (parent_mask[1] & done_counting) + 
                   (parent_mask[2] & ack);

  assign B3_next = in_degree[0];
  assign S_next = in_degree[1];
  assign S1_next = in_degree[2];
  assign Count_next = in_degree[3];

  // Compute out-degree as sum of active child edges
  wire [3:0] child_mask = state[7:4];
  wire out_degree = (child_mask[0] & d) + 
                    (child_mask[1] & done_counting) + 
                    (child_mask[2] & ack);

  assign Wait_next = out_degree[0];
  assign done = out_degree[1];
  assign counting = out_degree[2];
  assign shift_ena = out_degree[3];

endmodule

module adder_32bit(A,B,S,C32);
