     reg [32:1] B_reg;

     assign C32 = A_reg[1] | B_reg[1];
     assign S = A_reg[32:1] + B_reg[32:1];

     always @(A[0], B[0]) begin
         A_reg <= A + 1;
     end

     always @(B[0]) begin
