module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire [8:0] c; // Carry signals (c[0] is carry-in for bit 0)
    assign c[0] = cin;

    // Generate full adder stages using logical operations
    genvar i;
    generate
        for (i=0; i<8; i=i+1) begin: adder_stage
            assign sum[i] = a[i] ^ b[i] ^ c[i];
            assign c[i+1] = (a[i] & b[i]) | (b[i] & c[i]) | (a[i] & c[i]);
        end
    endgenerate

    // Overflow detection: OR of upper two MSB carry signals
    assign cout = c[7] | c[8];

endmodule

