module comparator_3bit (
    input [2:0] A,
    input [2:0] B,
    output A_greater,
    output A_equal,
    output A_less
);
    wire eq_bit2, eq_bit1, eq_bit0;
    wire term1, term2, term3;
    wire x_gt_y, x_lt_y;

    // Equality bits
    xnor (eq_bit2, A[2], B[2]);
    xnor (eq_bit1, A[1], B[1]);
    xnor (eq_bit0, A[0], B[0]);

    // All equal (A_less)
    and (term1, eq_bit2, eq_bit1);
    and (term2, term1, eq_bit0);
    not (A_less, term2);

    // A > B (x_gt_y)
    wire not_A2, not_A1, not_A0;
    wire termA, termB, termC;
    not (not_A2, A[2]);
    not (not_A1, A[1]);
    not (not_A0, A[0]);
    and (termA, not_A2, eq_bit2);
    and (termB, not_A1, eq_bit1, eq_bit0);
    and (termC, not_A0, eq_bit0);
    or (x_gt_y, termA, termB, termC);

    // A < B (x_lt_y)
    wire not_B2, not_B1, not_B0;
    wire termL2, termL3, termL4;
    not (not_B2, B[2]);
    not (not_B1, B[1]);
    not (not_B0, B[0]);
    and (termL2, eq_bit2, not_B1);
    and (termL3, eq_bit1, eq_bit0, not_B2);
    and (termL4, eq_bit0, not_B0);
    or (x_lt_y, termL2, termL3, termL4);

    // Outputs
    or (A_greater, x_gt_y, x_lt_y);
    assign A_equal = x_gt_y;
endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);
    // Declare wires for intermediate calculations
    wire [3:0] P, G;    // Propagate and Generate signals
    wire [4:0] C;       // Carry signals (C[0] is carry-in for bit 0)

    // Compute propagate (P) and generate (G) for each bit
    assign P = A ^ B;
    assign G = A & B;

    // Carry chain calculations
    assign C[0] = G[0];                          // Initial carry-in is 0, so C[0] = G0
    assign C[1] = G[1] | (P[1] & C[0]);
    assign C[2] = G[2] | (P[2] & C[1]);
    assign C[3] = G[3] | (P[3] & C[2]);
    assign C[4] = G[3] | (P[3] & C[3]);         // Final carry-out

    // Assign outputs based on computed values
    assign A_greater = C[4];
    assign A_equal  = P[3] & C[3];
    assign A_less = C[3];
endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

reg prev_in;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		prev_in <= 1'b0;
		rise <= 1'b0;
		down <= 1'b0;
		end
	else begin
		prev_in <= a;
		rise <= (prev_in == 1'b0) && (a == 1'b1);
		down <= (prev_in == 1'b1) && (a == 1'b0);
		end
end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;
    localparam COUNTER_WIDTH = $clog2(NUM_DIV);
    reg [COUNTER_WIDTH-1:0] counter;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 0;
            clk_div <= 0;
        end else begin
            if (counter == NUM_DIV - 1) begin
                counter <= 0;
                clk_div <= ~clk_div;
            end else begin
                counter <= counter + 1;
            end
        end
    end

    assign clk_div = clk_div;

endmodule

