	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	reg [3:0] stage1, stage2;

	// First stage flip-flops
	always @(posedge clk_b or negedge arstn) begin
		if (!arstn) begin
			stage1 <= 4'b0;
		end else begin
			if (brstn) begin
				stage1 <= data_in;
			end
		end
	end

	// Second stage flip-flops
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			stage2 <= 4'b0;
		end else begin
			if (data_en) begin
				stage2 <= stage1;
			end
		end
	end

	// Output assignment
	always @(*) begin
		dataout = stage2;
	end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [1:0] count_p, count_n;
reg start_p, start_n;
reg prev_p, prev_n;

// Positive edge counter
always @(posedge CLK, posedge RST) begin
    if (RST) begin
        count_p <= 2'b0;
        start_p <= 1'b1;
        prev_p <= 1'b0;
    end else if (IN) begin
        if (count_p == 2'b10) begin
            count_p <= 2'b00;
            start_p <= 1'b1;
        end else begin
            count_p <= count_p + 1;
        end
        prev_p <= MATCH;
    end else begin
        count_p <= 2'b00;
        start_p <= 1'b0;
        prev_p <= 1'b0;
    end
end

// Negative edge counter
always @(negedge CLK, posedge RST) begin
    if (RST) begin
        count_n <= 2'b0;
        start_n <= 1'b1;
        prev_n <= 1'b0;
    end else if (IN) begin
        if (count_n == 2'b10) begin
            count_n <= 2'b00;
            start_n <= 1'b1;
        end else begin
            count_n <= count_n + 1;
        end
        prev_n <= MATCH;
    end else begin
        count_n <= 2'b00;
        start_n <= 1'b0;
        prev_n <= 1'b0;
    end
end

// Output logic
always @(posedge CLK, posedge RST) begin
    if (RST) begin
        MATCH <= 1'b0;
    end else if (IN) begin
        if ((count_p == 2'b10 && start_p) || 
            (count_n == 2'b10 && start_n)) begin
            MATCH <= ~MATCH;
        end else begin
            MATCH <= 1'b0;
        end
    end else begin
        MATCH <= 1'b0;
    end
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);
    reg [3:0] lfsr_reg;
    reg [3:0] counter_reg;
    wire feedback;

    // Feedback from the leftmost bit (tap at 4'b1000)
    assign feedback = lfsr_reg[3];

    // Output is the LSB of the LFSR
    assign dout = lfsr_reg[0];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            lfsr_reg <= 4'b0;
            counter_reg <= 4'b0;
        end else begin
            if (counter_reg == 4'd15) begin
                // Reset LFSR and restart counter when reaching max count
                lfsr_reg <= 4'b0;
                counter_reg <= 4'b0;
            end else begin
                // Update LFSR with feedback and shift
                lfsr_reg <= {feedback, lfsr_reg[3:1]};
                // Increment counter without rst_n
                counter_reg <= counter_reg + 1;
            end
        end
    end

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

     localparam [2:0] 
        state_init = 3'd0,
        state_1    = 3'd1,
        state_2    = 3'd2,
        state_3    = 3'd3,
        state_4    = 3'd4;

     reg [2:0] current_state, next_state;

     // State register with asynchronous active-low reset
     always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
           current_state <= state_init;
        else
           current_state <= next_state;
     end

     // Next state logic
     always @(*) begin
        case (current_state)
           state_init: next_state = data_in ? state_1 : state_init;
           state_1:    next_state = data_in ? state_1 : state_2;
           state_2:    next_state = data_in ? state_3 : state_2;
           state_3:    next_state = data_in ? state_4 : state_3;
           state_4:    next_state = state_init;
           default:    next_state = state_init;
        endcase
     end

     // Output is high only in the final state
     assign sequence_detected = (current_state == state_4);

endmodule
